# Write your MySQL query statement below
select a.reports_to as employee_id, name, reports_count, average_age from (select employee_id, reports_to, count(*) as reports_count, round(avg(age)) as average_age from employees group by reports_to having reports_to is not null) a join (select * from employees) b on a.reports_to = b.employee_id order by a.reports_to